        findMinMax(root, ref min, ref max, 0);

        for (int line = min; line <= max; line++) {
            List<int> verticalNodes = new List<int>();
            collectVerticalLine(root, line, verticalNodes);
            res.Add(verticalNodes);
        }

        return res;
    }

