        // storing node value and level
        verticalLines[hd].Add(new int[] { root.data, lvl });

        // Recur for left and right subtrees
        dfs(root.left, hd - 1, lvl + 1, verticalLines);
        dfs(root.right, hd + 1, lvl + 1, verticalLines);
    }

